import apiClient from './client'
import type { Page, PageParams } from './page'

export type AlertRuleScope = 'global' | 'node' | 'node_group'
export type AlertRuleConditionType = 'json_dsl' | 'promql'
export type AlertRuleSeverity = 'critical' | 'warning' | 'info'

export interface AlertRuleRead {
  id: number
  name: string
  description?: string | null
  scope: AlertRuleScope
  scope_target?: string | null
  condition_type: AlertRuleConditionType
  condition: string
  pending_duration_seconds: number
  resolve_duration_seconds: number
  severity: AlertRuleSeverity
  enabled: boolean
  notification_channel_ids: number[]
  created_at: string
  updated_at: string
}

export interface AlertRuleCreate {
  name: string
  description?: string
  scope: AlertRuleScope
  scope_target?: string
  condition_type: AlertRuleConditionType
  condition: string
  pending_duration_seconds?: number
  resolve_duration_seconds?: number
  severity: AlertRuleSeverity
  enabled?: boolean
  notification_channel_ids?: number[]
}

export interface AlertRuleUpdate {
  name?: string
  description?: string
  scope?: AlertRuleScope
  scope_target?: string
  condition_type?: AlertRuleConditionType
  condition?: string
  pending_duration_seconds?: number
  resolve_duration_seconds?: number
  severity?: AlertRuleSeverity
  enabled?: boolean
  notification_channel_ids?: number[]
}

export interface ToggleResponse {
  id: number
  enabled: boolean
}

export interface EvaluateResponse {
  rule_id: number
  node_id: string
  state: string
  evaluated_at: string
}

export type AlertRuleListParams = PageParams

export async function getAlertRules(params?: AlertRuleListParams): Promise<Page<AlertRuleRead>> {
  const response = await apiClient.get<Page<AlertRuleRead>>('/v1/alert-rules', { params })
  return response.data
}

export async function createAlertRule(data: AlertRuleCreate): Promise<AlertRuleRead> {
  const response = await apiClient.post<AlertRuleRead>('/v1/alert-rules', data)
  return response.data
}

export async function getAlertRule(ruleId: number): Promise<AlertRuleRead> {
  const response = await apiClient.get<AlertRuleRead>(`/v1/alert-rules/${ruleId}`)
  return response.data
}

export async function updateAlertRule(ruleId: number, data: AlertRuleUpdate): Promise<AlertRuleRead> {
  const response = await apiClient.put<AlertRuleRead>(`/v1/alert-rules/${ruleId}`, data)
  return response.data
}

export async function deleteAlertRule(ruleId: number): Promise<void> {
  await apiClient.delete(`/v1/alert-rules/${ruleId}`)
}

export async function toggleAlertRule(ruleId: number): Promise<AlertRuleRead> {
  const response = await apiClient.post<AlertRuleRead>(`/v1/alert-rules/${ruleId}/toggle`)
  return response.data
}

export async function evaluateAlertRule(ruleId: number, nodeId: string): Promise<EvaluateResponse> {
  const response = await apiClient.post<EvaluateResponse>(
    `/v1/admin/alert-detector/evaluate/${ruleId}?node_id=${encodeURIComponent(nodeId)}`
  )
  return response.data
}
